"""Simple, obviously-correct reference model (dict based) for cross-checking."""
import json

MAXVAR = 4611686018427387903

class Err(Exception):
    def __init__(self, code, frame=None):
        self.code = code; self.frame = frame

class S:
    def __init__(self):
        self.highest = 0; self.final_size = None; self.reset = False; self.stopped = False
        self.data = {}   # offset -> byte value
        self.delivered = bytearray()

class C:
    def __init__(self):
        self.highest = 0; self.data = {}
        self.contig = bytearray()

def store_bytes(data, offset, payload, policy):
    """returns new dict or raises Err(PROTOCOL_VIOLATION)"""
    new = dict(data)
    for i, b in enumerate(payload):
        o = offset + i
        if o in new:
            if new[o] != b:
                if policy == "reject":
                    raise Err("PROTOCOL_VIOLATION")
                # first wins: keep
            else:
                pass
        else:
            new[o] = b
    return new

def contiguous(data):
    out = bytearray(); o = 0
    while o in data:
        out.append(data[o]); o += 1
    return out

def allowed(level, fr):
    t = fr["type"]
    if t in ("PADDING","PING"): return True
    if t in ("ACK","CRYPTO"): return level in ("I","H","A")
    if t in ("STREAM","RESET_STREAM","STOP_SENDING"): return level in ("Z","A")
    if t == "CLOSE": return (level in ("Z","A")) if fr["app"] else True
    return False

def contains(sent, lo, hi):
    pos = lo
    for s, e in sent:
        if e < pos: continue
        if s > pos: return False
        if e >= hi: return True
        pos = e + 1
    return False

def replay(doc):
    results = []
    for tr in doc["traces"]:
        cfg = tr["config"]; events = tr["events"]
        keys = {"I":"live","H":"absent","Z":("live" if cfg["early"] else "absent"),"A":"absent"}
        queue = []
        streams = {}
        crypto = {"I":C(),"H":C(),"A":C()}
        total = 0
        pns = {"I":set(),"H":set(),"A":set()}
        state = "open"; code=None; at_ms=None; source=None; peer_code=None; last=0
        res = {}
        def rec(e,p,st,rs,t,f): res[(e,p)] = {"event":e,"packet":p,"status":st,"reason":rs,"at_ms":t,"frame":f}
        def terminate(newstate, c, t, src, pc):
            nonlocal state, code, at_ms, source, peer_code
            state=newstate; code=c; at_ms=t; source=src; peer_code=pc
            for q in list(queue):
                rec(q[0],q[1],"dropped","CONNECTION_CLOSED",t,None)
            queue.clear()
        def do_packet(e,p,frames,level,pn,auth,t,size,from_queue):
            if not from_queue and level=="I" and size < 1200:
                rec(e,p,"dropped","INITIAL_TOO_SMALL",t,None); return
            if level=="Z" and not cfg["early"]:
                rec(e,p,"dropped","EARLY_REJECTED",t,None); return
            if keys[level]=="discarded":
                rec(e,p,"dropped","KEYS_DISCARDED",t,None); return
            if keys[level]=="absent":
                if len(queue) < cfg["buffer_packets"]:
                    queue.append((e,p,level,pn,auth,frames,t))
                else:
                    rec(e,p,"dropped","BUFFER_FULL",t,None)
                return
            if not auth:
                rec(e,p,"dropped","AUTH",t,None); return
            space = "A" if level in ("Z","A") else level
            if pn in pns[space]:
                rec(e,p,"duplicate","DUPLICATE",t,None); return
            # frames
