"""Independent reference model (dict-based byte storage) for cross-checking."""
import json

MAXVAR = 4611686018427387903

class Err(Exception):
    def __init__(self, code, frame=None):
        Exception.__init__(self, code)
        self.code = code
        self.frame = frame


def allowed(level, fr):
    t = fr["type"]
    if t in ("PADDING", "PING"):
        return True
    if t in ("ACK", "CRYPTO"):
        return level in ("I", "H", "A")
    if t in ("STREAM", "RESET_STREAM", "STOP_SENDING"):
        return level in ("Z", "A")
    if t == "CLOSE":
        return (level in ("Z", "A")) if fr["app"] else True
    return False


def contains(sent, lo, hi):
    pos = lo
    for s, e in sent:
        if e < pos:
            continue
        if s > pos:
            return False
        if e >= hi:
            return True
        pos = e + 1
    return False


class Stream:
    def __init__(self):
        self.highest = 0
        self.final_size = None
        self.reset = False
        self.stopped = False
        self.data = {}
        self.delivered = bytearray()

    def copy(self):
        s = Stream()
        s.highest = self.highest
        s.final_size = self.final_size
        s.reset = self.reset
        s.stopped = self.stopped
        s.data = dict(self.data)
        s.delivered = bytearray(self.delivered)
        return s


class Crypto:
    def __init__(self):
        self.highest = 0
        self.data = {}
        self.contig = bytearray()

    def copy(self):
        c = Crypto()
        c.highest = self.highest
        c.data = dict(self.data)
        c.contig = bytearray(self.contig)
        return c


def contiguous(data):
    out = bytearray()
    o = 0
    while o in data:
        out.append(data[o])
        o += 1
    return out


def merge_bytes(data, offset, payload, policy):
    new = dict(data)
    for i, b in enumerate(payload):
        o = offset + i
        if o in new:
            if new[o] != b and policy == "reject":
                raise Err("PROTOCOL_VIOLATION")
        else:
            new[o] = b
    return new


