    def __init__(self, trace):
        self.tr = trace
        self.cfg = trace["config"]
        self.res = {}

    def rec(self, e, p, status, reason, t, frame):
        self.res[(e, p)] = {
            "event": e, "packet": p, "status": status, "reason": reason,
            "at_ms": t, "frame": frame,
        }

    def run(self):
        cfg = self.cfg
        events = self.tr["events"]
        self.keys = {"I": "live", "H": "absent",
                     "Z": ("live" if cfg["early"] else "absent"), "A": "absent"}
        self.queue = []
        self.streams = {}
        self.crypto = {"I": Crypto(), "H": Crypto(), "A": Crypto()}
        self.total = 0
        self.pns = {"I": set(), "H": set(), "A": set()}
        self.state = "open"
        self.code = None
        self.at_ms = None
        self.source = None
        self.peer_code = None
        self.last = 0

